import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan 0020 — the construction arena (a better game for a better player)","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/plans/0020-construction-arena.md","filePath":"vendored/graphopt/project/plans/0020-construction-arena.md"}`),a={name:`graphopt/project/plans/0020-construction-arena.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0020-—-the-construction-arena-a-better-game-for-a-better-player" tabindex="-1">Plan 0020 — the construction arena (a better game for a better player) <a class="header-anchor" href="#plan-0020-—-the-construction-arena-a-better-game-for-a-better-player" aria-label="Permalink to “Plan 0020 — the construction arena (a better game for a better player)”">​</a></h1><p>Status: drafted.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The meta-game experiment measured something precise: <strong>the pipeline <em>scheduling</em> game is shallow</strong> — the optimal arm-ordering is a fixed rule a trained guide converges to but cannot beat (<code>law-meta-game.md</code>, <code>guide-real-run.md</code>). That is a finding about <em>that</em> layer, not about learned play in general. The space that is actually deep — which objects to construct, compose, relax, specialize — was never given to a player. This plan defines the game where a learned player could have an edge, plus the honest bars for &quot;outperforms humans&quot;.</p><h2 id="the-game" tabindex="-1">The game <a class="header-anchor" href="#the-game" aria-label="Permalink to “The game”">​</a></h2><ul><li><strong>Board.</strong> The evidence store + the real corpus + the declared object set + the shipped law library. State is inspectable as data (proposals, regions, verdicts, pays).</li><li><strong>Moves — structured construction operations</strong> (each already proven mechanically in <code>object_synthesis</code>/<code>evidence</code>): <code>fold</code>, <code>lift</code>, <code>compose</code> (with guard transport), <code>auto_cond</code>, <code>relax_guard</code> <em>(new)</em>, <code>specialize</code> <em>(new)</em>, <code>ingest</code> (corpus direction).</li><li><strong>Referee.</strong> The existing eight-stage gauntlet. The player never decides equivalence (ADR 0003).</li><li><strong>Score.</strong> Admitted objects that <strong>pay on held-out real workloads</strong> — zoo-discipline: pay on seeded spellings does not count (the corpus-circular lesson).</li></ul><h2 id="reward-design-fixes-the-measured-failures" tabindex="-1">Reward design (fixes the measured failures) <a class="header-anchor" href="#reward-design-fixes-the-measured-failures" aria-label="Permalink to “Reward design (fixes the measured failures)”">​</a></h2><ul><li><strong>Dense partial credit</strong> — each gauntlet stage cleared is progress (reconstruct→measure→truth→novelty→typed-pay→closure→cert), so credit assignment reaches the construction that caused it.</li><li><strong>Hindsight attribution</strong> — an ingest/compose action is scored on what it later enables, not its immediate delta.</li><li><strong>Holdout gating</strong> — reward reads <code>fires/pays</code> on a split the player cannot write into.</li></ul><h2 id="bars-honest-measurable" tabindex="-1">Bars (honest, measurable) <a class="header-anchor" href="#bars-honest-measurable" aria-label="Permalink to “Bars (honest, measurable)”">​</a></h2><ol><li>Beat the fixed-rule baseline on <em>admitted-paying</em> objects per oracle call — if the optimum is still a rule, the game is honestly shallow at this level too.</li><li>Machine-admitted paying objects on the held-out zoo vs the human-authored library&#39;s on the same code — the &quot;outperforms humans&quot; bar.</li></ol><h2 id="phases" tabindex="-1">Phases <a class="header-anchor" href="#phases" aria-label="Permalink to “Phases”">​</a></h2><ol><li><strong>Arena</strong> — <code>arena.py</code>: actions as data, state view, referee wiring, episode driver.</li><li><strong>Baselines + depth probe</strong> — fixed-rule, random, enumeration players; does context change the best move? (Depth gate.)</li><li><strong>The player</strong> — learned policy (RL or lookahead search) on the arena, vs baselines.</li><li><strong>Human bar</strong> — machine vs human authored laws, scored on the zoo.</li></ol>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};